# -*- coding: utf-8 -*-
from taf.fdsw.rc.clients.http.http_client import RCHttpClient
from taf.fdsw.rc.interfaces.FDSW19.fdsw import FDSW19
from taf.fdsw.rc.interfaces.FDSW19A.autoconnection import AutoConfiguration19A


class FDSW19A(FDSW19):
    API_VERSION = "1.1"
    API_SCHEMA_VERSION = "2.0"
    VERSION_NAME = 'FDSW19A'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW19A, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
        self._client = RCHttpClient(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
            secure=secure,
            api_version=self.API_VERSION,
            api_schema_version=self.API_SCHEMA_VERSION
        )

        self._client.connect()
        self.autoconnection = AutoConfiguration19A(client=self._client)
